def anonymizeDataframeColumn(df, anonymizedColumn):
    def anonymize_text(text: str) -> str:
        # Initialize the recognizer and engines locally
        flair_recognizer = FlairRecognizer()
        registry = RecognizerRegistry()
        registry.add_recognizer(flair_recognizer)
        
        analyzer = AnalyzerEngine(registry=registry)
        anonymizer = AnonymizerEngine()
        
        if text:
            # Perform analysis
            results = analyzer.analyze(
                text=text,
                language="en",
                return_decision_process=True,
            )
            
            # Perform anonymization
            anonymized_results = anonymizer.anonymize(
                text=text,
                analyzer_results=results,
                operators={"DEFAULT": OperatorConfig("replace", {"new_value": "<ANONYMIZED>"})},
            )
            return anonymized_results.text
        else:
            return text
    
    @pandas_udf(StringType())
    def anonymize_series(s: pd.Series) -> pd.Series:
        return s.apply(anonymize_text)
    
    # Apply the UDF
    anonymized_df = df.withColumn(
        anonymizedColumn, anonymize_series(col(anonymizedColumn))
    )
    return anonymized_df
